package com.learnagent.workspace;import org.springframework.web.bind.annotation.*;@RestController@RequestMapping("/api/workspace-files")public class WorkspaceFileController{private final WorkspaceFileService service;public WorkspaceFileController(WorkspaceFileService service){this.service=service;}@GetMapping public FileValue read(@RequestParam String path){return new FileValue(path,service.read(path));}@PutMapping public FileValue write(@RequestParam String path,@RequestBody WorkspaceService.FileWrite body){service.write(path,body.content());return new FileValue(path,body.content());}public record FileValue(String path,String content){}}
